// App.js - version corrigée
import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate, useLocation, useNavigate } from 'react-router-dom';

import Header from './components/Clients/Widgets/Header/Header';
import Footer from './components/Clients/Widgets/Footer/Footer';

import Login from './components/Clients/Auth/Login';
import Register from './components/Clients/Auth/Register';

import Home from './components/Clients/Home/Home';
import Dashboard from './components/Clients/Widgets/DashboardLayout';
import ProtectedRoute from './components/Clients/Auth/ProtectedRoute';

import Contact from './components/Clients/Contact/Contact';
import Portfolio from './components/Clients/Portfolio/Portfolio';
import Services from './components/Clients/Services/Services';

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const location = useLocation();
  const navigate = useNavigate();

  // Vérifier la session user
  useEffect(() => {
    const userDataStr = localStorage.getItem('userData');
    const token = localStorage.getItem('authToken');

    if (userDataStr && token) {
      try {
        const userData = JSON.parse(userDataStr);
        const role = localStorage.getItem('userRole') || userData.role || 'user';

        setUserRole(role);
        setIsAuthenticated(true);
      } catch (error) {
        console.error('Erreur parsing userData:', error);
        localStorage.clear();
      }
    }
    setIsLoading(false);
  }, []);

  // Redirection automatique après login
  useEffect(() => {
    if (isAuthenticated && userRole && location.pathname === '/login') {
      if (userRole === 'admin') {
        navigate('/admin', { replace: true });
      } else {
        navigate('/dashboard', { replace: true });
      }
    }
  }, [isAuthenticated, userRole, location.pathname, navigate]);

  // Connexion
  const handleLogin = (userData) => {
    localStorage.setItem('userData', JSON.stringify(userData));
    const role = userData.role || 'user';
    localStorage.setItem('userRole', role);
    setUserRole(role);
    setIsAuthenticated(true);
  };

  // Déconnexion
  const handleLogout = () => {
    localStorage.removeItem('authToken');
    localStorage.removeItem('userData');
    localStorage.removeItem('userRole');
    localStorage.removeItem('userEmail');
    setIsAuthenticated(false);
    setUserRole(null);
    navigate('/login', { replace: true });
  };

  // Loader
  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white dark:bg-neutral-950">
        <div className="text-center">
          <div className="h-12 w-12 border-4 border-primary-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
          <p className="mt-4 text-neutral-600 dark:text-neutral-400">Chargement...</p>
        </div>
      </div>
    );
  }

  // Cacher Header / Footer sur dashboards
  const hideUi = location.pathname.startsWith('/dashboard') || 
                  location.pathname.startsWith('/admin') ||
                  location.pathname.startsWith('/login') ||
                  location.pathname.startsWith('/register');

  return (
    <>
      {!hideUi && <Header isAuthenticated={isAuthenticated} onLogout={handleLogout} />}

      <div className="min-h-screen bg-white dark:bg-neutral-950 text-neutral-900 dark:text-white">
        <Routes>
          {/* HOME */}
          <Route path="/" element={<Home />} />

          {/* LOGIN / REGISTER */}
          <Route
            path="/login"
            element={
              isAuthenticated ? (
                <Navigate to={userRole === 'admin' ? "/admin" : "/dashboard"} replace />
              ) : (
                <Login onLogin={handleLogin} />
              )
            }
          />
          <Route
            path="/register"
            element={
              isAuthenticated ? (
                <Navigate to={userRole === 'admin' ? "/admin" : "/dashboard"} replace />
              ) : (
                <Register />
              )
            }
          />

          {/* DASHBOARD USER */}
          <Route
            path="/dashboard/*"
            element={
              <ProtectedRoute 
                isAuthenticated={isAuthenticated} 
                requiredRole="user" 
                userRole={userRole}
              >
                <Dashboard onLogout={handleLogout} isAdmin={false} />
              </ProtectedRoute>
            }
          />

          {/* DASHBOARD ADMIN */}
          <Route
            path="/admin/*"
            element={
              <ProtectedRoute 
                isAuthenticated={isAuthenticated} 
                requiredRole="admin" 
                userRole={userRole}
              >
                <Dashboard onLogout={handleLogout} isAdmin={true} />
              </ProtectedRoute>
            }
          />

          {/* PAGES CLIENT */}
          <Route path="/contact" element={<Contact />} />
          <Route path="/portfolio" element={<Portfolio />} />
          <Route path="/services" element={<Services />} />

          {/* NOT FOUND */}
          <Route path="*" element={
            <Navigate to={
              isAuthenticated 
                ? (userRole === 'admin' ? "/admin" : "/dashboard") 
                : "/"
            } replace />
          } />
        </Routes>
      </div>

      {!hideUi && <Footer />}
    </>
  );
}

// Wrapper Router
export default function AppWrapper() {
  return (
    <Router>
      <App />
    </Router>
  );
}
